class BowlingGame:
    def __init__(self):
        self.rolls = []
        self._frame = 0
        self._throws = 0

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise ValueError(f"Roll cannot score {pins} points")
        if self._frame == 10:
            raise ValueError("Cannot roll if game already has ten frames")
        self.rolls.append(pins)
        self._throws += 1
        if self._frame < 9:
            if self._throws == 1 and pins == 10:
                self._frame += 1
                self._throws = 0
            elif self._throws == 2:
                if self.rolls[-2] + pins > 10:
                    raise ValueError(
                        "Two rolls in a frame cannot score more than 10 points"
                    )
                self._frame += 1
                self._throws = 0
        else:
            if self._throws == 2:
                a, b = self.rolls[-2], self.rolls[-1]
                if a < 10 and a + b > 10:
                    raise ValueError(
                        "Two rolls in a frame cannot score more than 10 points"
                    )
                if a + b < 10:
                    self._frame = 10
            elif self._throws == 3:
                a, b = self.rolls[-2], self.rolls[-1]
                if a < 10 or b < 10:
                    if b + pins > 10:
                        raise ValueError(
                            "Two rolls in a frame cannot score more than 10 points"
                        )
                self._frame = 10

    def score(self):
        if self._frame < 10:
            raise ValueError("Game is not complete")
        rolls = self.rolls
        total = 0
        i = 0
        for _ in range(10):
            if rolls[i] == 10:
                total += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == 10:
                total += 10 + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total

